#!/usr/bin/env bun
// Generates the pages of oddjobkit.com from each tool repo's CHROMEWEBSTORE.md:
//   index.html (home), privacy/<tool>/index.html, privacy/index.html, tools/index.html, assets/icons/<tool>.png, sitemap.xml
// The home page's own copy (statement, "How we build", contact) lives in homePage() below; its tool cards come from the same data as /tools/.
// No dependencies. Re-running overwrites generated files only. How the source file is read is
// documented in README.md ("Keeping CHROMEWEBSTORE.md parseable").
//
//   bun scripts/build-pages.ts [--repos <dir>] [--dry]
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

// ── Configuration ────────────────────────────────────────────────────────────────────────────
const SITE = resolve(import.meta.dir, "..");
const argv = process.argv.slice(2);
const flag = (name: string) => argv.indexOf(name);
const REPOS = resolve(flag("--repos") >= 0 ? argv[flag("--repos") + 1]! : join(SITE, "..", "repos"));
const DRY = flag("--dry") >= 0;
const ORIGIN = "https://oddjobkit.com";
const CONTACT = "oddjobkit@gmail.com";
/** Tools whose first release is next. Every other tool is listed as "not yet released". */
const FOCUS = ["hexpick", "picktext", "tabvault"];
/** Repos that are public on github.com/oddjobkit. Until a tool is here its source line says "available at release". */
const PUBLIC_REPOS: string[] = [];
/** Folders under repos/ that have a CHROMEWEBSTORE.md but are not tools. */
const NOT_TOOLS = ["extension-template"];
const GENERATED = "<!-- generated by scripts/build-pages.ts; edit CHROMEWEBSTORE.md in the tool repo, not this file -->";

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const today = (() => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; })();
const longDate = (iso: string) => { const [y, m, d] = iso.split("-").map(Number); return `${d} ${MONTHS[m! - 1]} ${y}`; };

// ── Markdown reading helpers ─────────────────────────────────────────────────────────────────
interface Section { level: 2 | 3; title: string; body: string[] }

/** Split into ## and ### sections. A ### section ends at the next ## or ###. Fenced blocks are never split. */
function sections(lines: string[]): Section[] {
  const out: Section[] = [];
  let cur: Section | null = null;
  let fence = false;
  for (const line of lines) {
    if (/^```/.test(line)) fence = !fence;
    const h = !fence && line.match(/^(##|###)\s+(.*?)\s*$/);
    if (h) { cur = { level: h[1]!.length as 2 | 3, title: h[2]!, body: [] }; out.push(cur); }
    else cur?.body.push(line);
  }
  return out;
}

/** The paragraph under a `**Label** ...` line: first non-blank line after it that is not a "(note)" line. */
function labelled(lines: string[], label: RegExp): string | null {
  const i = lines.findIndex((l) => new RegExp(`^\\*\\*(${label.source})`, label.flags).test(l));
  if (i < 0) return null;
  const para: string[] = [];
  for (let j = i + 1; j < lines.length; j++) {
    const l = lines[j]!.trim();
    if (!l) { if (para.length) break; continue; }
    if (!para.length && l.startsWith("(")) continue;
    if (/^(#|\*\*|\|)/.test(l)) break;
    para.push(l);
  }
  return para.length ? para.join(" ") : null;
}

function tableRows(lines: string[], headerHas: RegExp): string[][] | null {
  const start = lines.findIndex((l) => l.trim().startsWith("|") && headerHas.test(l));
  if (start < 0) return null;
  const rows: string[][] = [];
  for (let j = start + 2; j < lines.length && lines[j]!.trim().startsWith("|"); j++) {
    rows.push(lines[j]!.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim()));
  }
  return rows;
}

// ── Parsing one CHROMEWEBSTORE.md ────────────────────────────────────────────────────────────
interface Perm { raw: string; names: string[]; type: string; why: string; none: boolean }
interface Tool {
  slug: string; name: string; short: string; purpose: string;
  perms: Perm[]; permLine: string;
  dataUse: string; nothingLeaves: boolean;
  stored: string[]; rest: string[];
  updated: string; version: string; itemId: string | null;
  hasIcon: boolean; warnings: string[];
}

const stripQuotes = (s: string) => s.replace(/^["“]\s*/, "").replace(/\s*["”]$/, "");

function parsePerms(secs: Section[]): Perm[] {
  const s = secs.find((x) => x.level === 2 && /^permissions?\b/i.test(x.title));
  const rows = s && tableRows(s.body, /permission/i);
  return (rows ?? []).filter((r) => r.length >= 3).map((r) => {
    const raw = r[0]!;
    const ticks = [...raw.matchAll(/`([^`]+)`/g)].map((m) => m[1]!);
    const plain = raw.replace(/\(.*$/, "").trim();
    const none = /^\(?\s*none\s*\)?$/i.test(raw);
    return { raw, names: none ? [] : ticks.length ? ticks : plain.split(/\s*,\s*/).filter(Boolean), type: r[1]!.replace(/`/g, ""), why: r.slice(2).join(" | "), none };
  });
}

const isWildcardHost = (n: string) => /^(https?|\*):\/\/\*\/\*$|^<all_urls>$/.test(n);
function permLine(perms: Perm[]): string {
  const req: string[] = [];
  const opt: string[] = [];
  for (const p of perms) {
    const isHost = /host/.test(p.type);
    const label = isHost ? [...new Set(p.names.map((n) => (isWildcardHost(n) ? "all sites" : n)))] : p.names;
    (/^optional/.test(p.type) ? opt : req).push(...label);
  }
  const uniq = (a: string[]) => [...new Set(a)];
  const parts = [req.length ? `Permissions: ${uniq(req).join(", ")}` : opt.length ? "No required permissions" : "No permissions"];
  if (opt.length) parts.push(`Optional: ${uniq(opt).join(", ")}`);
  return parts.join(" · ");
}

/** Policy paragraphs: the first blockquote or fenced block of the policy section, one paragraph per line. */
function policyParagraphs(secs: Section[]): string[] | null {
  const byTitle = secs.find((s) => s.level === 3 && /privacy[- ](policy|page)\s+text/i.test(s.title))
    ?? secs.find((s) => s.level === 2 && /^privacy[- ]?polic/i.test(s.title));
  if (!byTitle) return null;
  const b = byTitle.body;
  const q = b.findIndex((l) => l.startsWith(">"));
  const f = b.findIndex((l) => /^```/.test(l));
  let text: string[] = [];
  if (q >= 0 && (f < 0 || q < f)) {
    for (let j = q; j < b.length && b[j]!.startsWith(">"); j++) text.push(b[j]!.replace(/^>\s?/, ""));
  } else if (f >= 0) {
    for (let j = f + 1; j < b.length && !/^```/.test(b[j]!); j++) text.push(b[j]!);
  } else return null;
  return text.map((l) => l.trim()).filter(Boolean);
}

function dataUse(secs: Section[], all: string[]): string | null {
  // 1. a "Data-use sentence" or "Data-use statement" heading, 2. a `**Data-use statement ...:**` label,
  // 3. the answer on the "Does the extension collect user data?" line, 4. the paragraph under that line.
  const h = secs.find((s) => s.level === 3 && /data[- ]use (sentence|statement)/i.test(s.title));
  const first = h?.body.map((l) => l.trim()).find(Boolean);
  if (first) return stripQuotes(first);
  const lab = labelled(all, /Data-use (statement|sentence)/i);
  if (lab) return stripQuotes(lab);
  const i = all.findIndex((l) => /^\*\*Does the extension (collect|use) user data\?\*\*/.test(l));
  if (i < 0) return null;
  const same = all[i]!.replace(/^\*\*[^*]*\*\*\s*/, "").trim();
  if (same.split(/\s+/).length > 6 && !/^Dashboard answer/i.test(same)) return same;
  for (let j = i + 1; j < all.length; j++) {
    const l = all[j]!.trim();
    if (!l || l.startsWith("<!--")) continue;
    if (/^(#|\||\*\*|-|>)/.test(l)) break;
    return l;
  }
  return null;
}

function parseTool(slug: string): Tool | null {
  const file = join(REPOS, slug, "CHROMEWEBSTORE.md");
  const md = readFileSync(file, "utf8");
  const lines = md.split("\n");
  const secs = sections(lines);
  const warnings: string[] = [];
  const warn = (m: string) => warnings.push(m);

  const h1 = lines.find((l) => l.startsWith("# "))?.replace(/^#\s+Chrome Web Store Listing\s*[:—–-]?\s*/i, "").trim();
  const name = labelled(lines, /Extension Name/) ?? h1 ?? "";
  if (!name || /__[A-Z_]+__/.test(name)) { console.warn(`skip ${slug}: no store name (placeholder or missing)`); return null; }

  const short = labelled(lines, /Short Description/) ?? "";
  const purpose = labelled(lines, /Single Purpose/) ?? "";
  if (!short) warn("no Short Description");
  if (!purpose) warn("no Single Purpose");

  const perms = parsePerms(secs);
  if (!perms.length) warn("no permissions table");

  const du = dataUse(secs, lines);
  if (!du) warn("no data-use text found");
  const dataRows = tableRows(lines, /Data Type.*Transmitted/i);
  const hdr = lines.find((l) => /Data Type.*Transmitted/i.test(l));
  const col = hdr ? hdr.replace(/^\||\|$/g, "").split("|").findIndex((c) => /transmitted/i.test(c)) : -1;
  const nothingLeaves = !!dataRows?.length && col >= 0 && dataRows.every((r) => /^no\b/i.test(r[col] ?? ""));

  // Policy text → title and contact removed, then sorted into "stored" and the rest.
  let paras = policyParagraphs(secs);
  if (!paras) { warn("no policy text (blockquote or fenced block under the Privacy Policy heading)"); paras = []; }
  paras = paras
    .map((p) => p.replace(/\s*Contact:\s*\S+@\S+?\.?$/i, "").trim())
    .filter((p) => p && !/^\**contact:/i.test(p));
  if (paras[0] && /privacy( policy)?\**\.?$/i.test(paras[0])) paras.shift(); // a title line like "Name: privacy"
  const STORED_LABEL = /^(\*\*)?(what (it|is) stor|it stores|stores\b|where it keeps|what it keeps|your sessions live)/i;
  const STORED_WORD = /\b(stor(e|es|ed|age)|keeps?|kept)\b/i;
  const body = paras.slice(1);
  let stored = body.filter((p) => STORED_LABEL.test(p) || STORED_WORD.test(p));
  let rest = paras.filter((p) => !stored.includes(p));
  if (!stored.length && paras.length) {
    const sentences = paras.flatMap((p) => p.split(/(?<=[.!?])\s+/)).filter((s) => STORED_WORD.test(s));
    if (sentences.length) { stored = [sentences.join(" ")]; warn("no paragraph about what is stored; used the policy sentences that mention storage"); }
    else warn("policy says nothing about storage; the section is omitted");
  }

  const head = lines.slice(0, 12).join("\n");
  const upd = head.match(/Last Updated:\s*(\d{4}-\d{2}-\d{2})/i)?.[1];
  const updated = upd ?? today;
  if (!upd) warn("no `Last Updated: YYYY-MM-DD` line; used today");

  let version = "";
  for (const p of ["public/manifest.json", "manifest.json"]) {
    const f = join(REPOS, slug, p);
    if (existsSync(f)) { try { version = JSON.parse(readFileSync(f, "utf8")).version ?? ""; } catch { /* fall through */ } break; }
  }
  if (!version) version = head.match(/Version:\s*(\d+\.\d+\.\d+)/)?.[1] ?? "";
  if (!version) {
    const rows = tableRows(lines, /Version\s*\|\s*Date/);
    version = rows?.at(-1)?.[0]?.match(/\d+\.\d+\.\d+/)?.[0] ?? "";
  }
  if (!version) warn("no version (manifest.json, `Version:` header or Version History table)");

  const idLine = lines.findIndex((l) => /item id/i.test(l));
  const idText = idLine >= 0 ? `${lines[idLine]} ${/^\*\*Item ID\*\*\s*$/.test(lines[idLine]!) ? lines[idLine + 1] ?? "" : ""}` : "";
  const itemId = idText.match(/\b[a-p]{32}\b/)?.[0] ?? null;

  const urlLine = labelled(lines, /Privacy Policy URL/);
  if (urlLine && !urlLine.replace(/\/$/, "").endsWith(`/privacy/${slug}`)) warn(`Privacy Policy URL is "${urlLine}", the page is /privacy/${slug}/`);

  const hasIcon = existsSync(join(REPOS, "ui", "icons", "out", slug, "icon-128.png"));
  if (!hasIcon) warn("no icon at ui/icons/out/<tool>/icon-128.png");

  return { slug, name, short, purpose, perms, permLine: permLine(perms), dataUse: du ?? "", nothingLeaves, stored, rest, updated, version, itemId, hasIcon, warnings };
}

// ── HTML ─────────────────────────────────────────────────────────────────────────────────────
const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const inline = (s: string) => esc(s).replace(/`([^`]+)`/g, "<code>$1</code>").replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
/** One policy paragraph; a leading "Label: text" gets a bold label. */
function para(p: string): string {
  const m = !p.startsWith("**") && p.match(/^([A-Z][A-Za-z', ]{2,45}):\s+(.+)$/);
  return m ? `<p><strong>${esc(m[1]!)}:</strong> ${inline(m[2]!)}</p>` : `<p>${inline(p)}</p>`;
}

const MARK = `<svg viewBox="0 0 32 32" aria-hidden="true"><rect width="32" height="32" rx="7" fill="#1b2433"/><rect x="7" y="7" width="8" height="8" rx="1.5" fill="#fff"/><circle cx="21" cy="11" r="4.25" fill="#f5ae39"/><rect x="7" y="17" width="8" height="8" rx="1.5" fill="#fff"/><rect x="17" y="17" width="8" height="8" rx="1.5" fill="#fff"/></svg>`;

function page(o: { title: string; desc: string; path: string; current?: "tools" | "privacy"; body: string; generated?: string }): string {
  const url = ORIGIN + o.path;
  const nav = (href: string, label: string, key: string) => `<a href="${href}"${o.current === key ? ' aria-current="page"' : ""}>${label}</a>`;
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(o.title)}</title>
<meta name="description" content="${esc(o.desc)}">
<link rel="canonical" href="${url}">
<meta property="og:title" content="${esc(o.title)}">
<meta property="og:description" content="${esc(o.desc)}">
<meta property="og:url" content="${url}">
<meta property="og:type" content="website">
<link rel="icon" href="/favicon.svg" type="image/svg+xml">
<link rel="stylesheet" href="/assets/site.css">
${o.generated ?? GENERATED}
</head>
<body>
<a class="skip" href="#main">Skip to content</a>
<header class="wrap site-head">
  <a class="brand" href="/">${MARK}Oddjob Kit</a>
  <nav class="site-nav" aria-label="Site">${nav("/tools/", "Tools", "tools")}${nav("/privacy/", "Privacy", "privacy")}</nav>
</header>
<main id="main" class="wrap">
${o.body}
</main>
<footer class="site-foot">
  <div class="wrap">
    <span>© ${today.slice(0, 4)} Oddjob Kit</span>
    <a href="mailto:${CONTACT}">${CONTACT}</a>
    <a href="https://github.com/oddjobkit">GitHub</a>
  </div>
</footer>
</body>
</html>
`;
}

const PERM_TYPE: Record<string, string> = { permissions: "", optional_permissions: "Optional", host_permissions: "Site access", optional_host_permissions: "Optional site access" };

function privacyPage(t: Tool): string {
  const perms = t.perms.length
    ? `<ul class="perms">\n${t.perms.map((p) => {
        const badge = PERM_TYPE[p.type] ?? p.type;
        const head = p.none ? "<strong>No permissions</strong>" : `<span>${inline(p.raw)}</span>`;
        return `    <li><div class="perm-head">${head}${badge ? `<span class="badge">${esc(badge)}</span>` : ""}</div><p>${inline(p.why)}</p></li>`;
      }).join("\n")}\n  </ul>`
    : `<p class="muted">This policy source lists no permissions table.</p>`;
  const source = PUBLIC_REPOS.includes(t.slug)
    ? `<a href="https://github.com/oddjobkit/${t.slug}">github.com/oddjobkit/${t.slug}</a>`
    : `<code>github.com/oddjobkit/${t.slug}</code>, available at release.`;
  const body = `<p class="crumbs"><a href="/privacy/">Privacy</a> / ${esc(t.name)}</p>
<h1>${esc(t.name)} — Privacy</h1>
<dl class="meta">
  <dt>Effective</dt><dd><time datetime="${t.updated}">${longDate(t.updated)}</time></dd>
${t.version ? `  <dt>Applies to</dt><dd>Version ${esc(t.version)}</dd>\n` : ""}  <dt>Listing</dt><dd><a href="/tools/#${t.slug}">On the tools page</a></dd>
</dl>
${t.purpose ? `<p class="lede">${inline(t.purpose)}</p>\n` : ""}
<section aria-labelledby="access">
  <h2 id="access">What it can access</h2>
  ${perms}
</section>

<section aria-labelledby="leaves">
  <h2 id="leaves">What leaves your device</h2>
${t.nothingLeaves ? `  <p class="assurance"><span class="dot" aria-hidden="true"></span>Nothing leaves your device.</p>\n` : ""}${t.dataUse ? `  <p>${inline(t.dataUse)}</p>\n` : ""}</section>
${t.stored.length ? `
<section aria-labelledby="stored">
  <h2 id="stored">What is stored</h2>
${t.stored.map((p) => "  " + para(p)).join("\n")}
</section>
` : ""}${t.rest.length ? `
<section aria-labelledby="more">
  <h2 id="more">More detail</h2>
${t.rest.map((p) => "  " + para(p)).join("\n")}
</section>
` : ""}
<section aria-labelledby="contact">
  <h2 id="contact">Contact</h2>
  <p><a href="mailto:${CONTACT}">${CONTACT}</a></p>
</section>

<section aria-labelledby="source">
  <h2 id="source">Source</h2>
  <p>${source}</p>
</section>`;
  return page({ title: `${t.name} — Privacy`, desc: `Privacy policy for ${t.name}: what it can access, what leaves your device and what it stores.`, path: `/privacy/${t.slug}/`, current: "privacy", body });
}


function homeToolRow(t: Tool): string {
  const action = t.itemId
    ? `<a class="store-link" href="https://chromewebstore.google.com/detail/${t.itemId}">Chrome Web Store</a>`
    : `<span class="pill">First release soon</span>`;
  return `    <li class="tool">
      ${t.hasIcon ? `<img class="tool-icon" src="/assets/icons/${t.slug}.png" alt="" width="64" height="64">` : "<span></span>"}
      <div class="tool-body">
        <h3>${esc(t.name)}</h3>
        <p class="tool-job">${inline(t.short || t.purpose)}</p>
        <p class="tool-perms">${esc(t.permLine)}</p>
        <p class="tool-links"><a href="/privacy/${t.slug}/">Privacy policy</a>${action}</p>
      </div>
    </li>`;
}

const HOME_GENERATED = "<!-- generated by scripts/build-pages.ts: the copy is in homePage(), the tool cards come from each tool repo's CHROMEWEBSTORE.md; edit those, not this file -->";

function homePage(tools: Tool[]): string {
  const first = tools.filter((t) => t.itemId || FOCUS.includes(t.slug));
  const body = `<section class="hero" aria-labelledby="top">
  <h1 id="top">Free Chrome extensions that each do one odd job well.</h1>
  <p class="lede">Single-purpose and production-grade. Every listing states its permissions and data use. Nothing is sold.</p>
  <p class="actions"><a class="store-link" href="/tools/">See the tools</a><a href="/privacy/">Read the privacy policies</a></p>
</section>

<section aria-labelledby="first">
  <h2 id="first">First releases</h2>
  <ul class="rows">
${first.map(homeToolRow).join("\n")}
  </ul>
  <p class="more"><a href="/tools/">All ${tools.length} tools, including those still in progress</a></p>
</section>

<section aria-labelledby="build">
  <h2 id="build">How we build</h2>
  <ul class="principles">
    <li><h3>No analytics inside extensions</h3><p>No tracking and no telemetry in any extension. Anything that does use the network is disclosed on the listing and in the privacy policy.</p></li>
    <li><h3>Minimal permissions</h3><p>Each tool asks for the smallest set that does its job, and every permission is explained in plain words.</p></li>
    <li><h3>Open source at release</h3><p>The source of each tool goes public on GitHub when the tool ships, so the claims can be checked.</p></li>
    <li><h3>Replies to reviews</h3><p>Store reviews get a reply within a week, and the support address is read by a person.</p></li>
  </ul>
</section>

<section aria-labelledby="contact">
  <h2 id="contact">Contact</h2>
  <p>Questions and bug reports: <a href="mailto:${CONTACT}">${CONTACT}</a>. Source: <a href="https://github.com/oddjobkit">github.com/oddjobkit</a>.</p>
</section>`;
  return page({ title: "Oddjob Kit — free single-purpose Chrome extensions", desc: "Free, single-purpose, production-grade Chrome extensions. One job each; permissions and data use are stated on every listing.", path: "/", body, generated: HOME_GENERATED });
}

const status = (t: Tool) => (t.itemId ? "On the Chrome Web Store" : FOCUS.includes(t.slug) ? "First release soon" : "Not yet released");

function toolRow(t: Tool): string {
  const store = t.itemId
    ? `<a class="store-link" href="https://chromewebstore.google.com/detail/${t.itemId}">Chrome Web Store</a>`
    : `<!-- store-link:${t.slug} placeholder; becomes a link when CHROMEWEBSTORE.md has an Item ID -->\n        <span class="store-slot" data-store-link="pending">Chrome Web Store page: added at release</span>`;
  return `    <li class="tool" id="${t.slug}">
      ${t.hasIcon ? `<img class="tool-icon" src="/assets/icons/${t.slug}.png" alt="" width="64" height="64">` : "<span></span>"}
      <div class="tool-body">
        <h3>${esc(t.name)}</h3>
        <p class="tool-job">${inline(t.short || t.purpose)}</p>
        <p class="tool-perms">${esc(t.permLine)}</p>
        <p class="tool-meta"><span class="pill">${status(t)}</span><code>${t.slug}</code>${t.version ? `<span>Version ${esc(t.version)}</span>` : ""}</p>
        <p class="tool-links">
        <a href="/privacy/${t.slug}/">Privacy policy</a>
        ${store}
        </p>
      </div>
    </li>`;
}

function toolsPage(tools: Tool[]): string {
  const next = tools.filter((t) => t.itemId || FOCUS.includes(t.slug));
  const later = tools.filter((t) => !next.includes(t));
  const group = (label: string, list: Tool[]) => (list.length ? `<h2 class="group-label">${label}</h2>\n  <ul class="rows">\n${list.map(toolRow).join("\n")}\n  </ul>` : "");
  const body = `<h1>Tools</h1>
<p class="lede">Small Chrome extensions that each do one odd job. Every tool lists the permissions it asks for and links to its privacy policy.</p>
  ${group("First releases", next)}
  ${group("Not yet released", later)}`;
  return page({ title: "Tools — Oddjob Kit", desc: "The Oddjob Kit tools: what each one does, the permissions it asks for, and its privacy policy.", path: "/tools/", current: "tools", body });
}

function privacyIndex(tools: Tool[]): string {
  const row = (t: Tool) => `    <li>
      <div class="policy-row"><a href="/privacy/${t.slug}/">${esc(t.name)}</a><span class="meta-line">${t.version ? `Version ${esc(t.version)} · ` : ""}Effective ${longDate(t.updated)}</span></div>
      <p class="tool-perms">${esc(t.permLine)}</p>
    </li>`;
  const body = `<h1>Privacy</h1>
<p class="lede">One policy per tool. Each says what the tool can access, what leaves your device and what it stores.</p>
  <ul class="rows">
${tools.map(row).join("\n")}
  </ul>`;
  return page({ title: "Privacy — Oddjob Kit", desc: "The privacy policy of every Oddjob Kit tool: what it can access, what leaves your device and what it stores.", path: "/privacy/", current: "privacy", body });
}

// ── Output ───────────────────────────────────────────────────────────────────────────────────
function write(rel: string, content: string) {
  if (DRY) return;
  const f = join(SITE, rel);
  mkdirSync(join(f, ".."), { recursive: true });
  writeFileSync(f, content);
}

const slugs = readdirSync(REPOS, { withFileTypes: true })
  .filter((d) => d.isDirectory() && !NOT_TOOLS.includes(d.name) && existsSync(join(REPOS, d.name, "CHROMEWEBSTORE.md")))
  .map((d) => d.name);
const parsed = slugs.map(parseTool).filter((t): t is Tool => !!t);
const rank = (t: Tool) => (FOCUS.includes(t.slug) ? FOCUS.indexOf(t.slug) : FOCUS.length);
const tools = parsed.sort((a, b) => rank(a) - rank(b) || a.name.localeCompare(b.name));

for (const t of tools) {
  write(`privacy/${t.slug}/index.html`, privacyPage(t));
  if (t.hasIcon && !DRY) {
    mkdirSync(join(SITE, "assets", "icons"), { recursive: true });
    copyFileSync(join(REPOS, "ui", "icons", "out", t.slug, "icon-128.png"), join(SITE, "assets", "icons", `${t.slug}.png`));
  }
}
write("index.html", homePage(tools));
write("privacy/index.html", privacyIndex(tools));
write("tools/index.html", toolsPage(tools));

// Remove generated privacy pages of tools that no longer have a CHROMEWEBSTORE.md (never anything else).
if (!DRY && existsSync(join(SITE, "privacy"))) {
  for (const d of readdirSync(join(SITE, "privacy"), { withFileTypes: true })) {
    const f = join(SITE, "privacy", d.name, "index.html");
    if (d.isDirectory() && !tools.some((t) => t.slug === d.name) && existsSync(f) && readFileSync(f, "utf8").includes(GENERATED)) rmSync(join(SITE, "privacy", d.name), { recursive: true });
  }
}

// sitemap.xml: home, the two indexes, every policy. lastmod never later than today.
const url = (p: string, lastmod?: string) => `<url><loc>${ORIGIN}${p}</loc>${lastmod ? `<lastmod>${lastmod > today ? today : lastmod}</lastmod>` : ""}</url>`;
const latest = tools.map((t) => t.updated).sort().at(-1);
write("sitemap.xml", `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${[url("/"), url("/tools/", latest), url("/privacy/", latest), ...tools.map((t) => url(`/privacy/${t.slug}/`, t.updated))].join("")}</urlset>\n`);

// Report
for (const t of tools) {
  console.log(`${t.slug.padEnd(13)} v${(t.version || "?").padEnd(6)} ${t.updated}  ${status(t).padEnd(20)} stored:${t.stored.length} more:${t.rest.length} leaves:${t.nothingLeaves ? "nothing" : "see text"}  ${t.permLine}`);
  for (const w of t.warnings) console.log(`  warning: ${w}`);
}
console.log(`\n${tools.length} tools${DRY ? " (dry run, nothing written)" : ""}; repos: ${REPOS}`);
